ship_event = {
	id = cstorms.1805
	title = cstorms.1805.name
	desc = {
		trigger = {
			text = cstorms.1805.desc
			if = {
				limit = { has_ship_flag = event_traumatized_leader }
				text = newline
				text = cstorms.1805.desc.traumatized
			}
		}
	}
	picture = GFX_evt_cosmic_storms_stormbound
	show_sound = event_faceoff_in_space
	is_triggered_only = yes
	location = from

	immediate = {
		fromfrom = {
			switch = {
				trigger = is_storm_type
				magnetic_storm = { prev.from.star = { set_carrier_flag = collect_alloys } }
				celestial_storm = { prev.from.star = { set_carrier_flag = collect_minerals } }
				shroud_storm = { prev.from.star = { set_carrier_flag = collect_zro } }
				nexus_storm = { prev.from.star = { set_carrier_flag = collect_multiple_resources } }
				default = { prev.from.star = { set_carrier_flag = collect_energy } }
			}
		}
		random_list = {
			90 = {}
			10 = {
				set_ship_flag = event_traumatized_leader
				leader = {
					add_trait = {
						trait = leader_trait_traumatized
					}
				}
			}
		}
	}

	option = {
		name = FASCINATING
		controller = {
			if = {
				limit = {
					prev.from.star = {
						OR = {
							has_carrier_flag = collect_energy
							has_carrier_flag = collect_multiple_resources
						}
					}
				}
				add_monthly_resource_mult = {
					resource = energy
					value = @tier4materialreward
					min = @tier4materialmin
					max = @tier4materialmax
				}
			}
			if = {
				limit = {
					prev.from.star = {
						OR = {
							has_carrier_flag = collect_alloys
							has_carrier_flag = collect_multiple_resources
						}
					}
				}
				add_monthly_resource_mult = {
					resource = alloys
					value = @tier3materialreward
					min = @tier3materialmin
					max = @tier3materialmax
				}
			}
			if = {
				limit = {
					prev.from.star = {
						OR = {
							has_carrier_flag = collect_minerals
							has_carrier_flag = collect_multiple_resources
						}
					}
				}
				add_monthly_resource_mult = {
					resource = minerals
					value = @tier4materialreward
					min = @tier4materialmin
					max = @tier4materialmax
				}
			}
			if = {
				limit = {
					prev.from.star = {
						has_carrier_flag = collect_zro
					}
				}
				add_monthly_resource_mult = {
					resource = sr_zro
					value = @tier3materialreward
					min = @tier3materialmin
					max = @tier3materialmax
				}
			}
			add_tech_option_or_research_effect = {
				TECH = tech_ship_hull_storm_breaker_1
				PROGRESS = 0.1
				CATEGORY = engineering_research
			}
		}
		if = {
			limit = { has_ship_flag = event_traumatized_leader }
			tooltip = {
				leader = {
					add_trait = {
						trait = leader_trait_traumatized
					}
				}
			}
		}
	}

	after = {
		hidden_effect = {
			if = {
				limit = { has_ship_flag = event_traumatized_leader }
				remove_ship_flag = event_traumatized_leader
			}
			from.star = {
				remove_carrier_flag = collect_energy
				remove_carrier_flag = collect_alloys
				remove_carrier_flag = collect_minerals
				remove_carrier_flag = collect_zro
				remove_carrier_flag = collect_multiple_resources
			}
		}
	}
}

